function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

const MAX_SESSION_ID_LENGTH = 128;

type Validator = (message: Record<string, unknown>) => ValidationResult;

const VALIDATORS: Record<string, Validator | undefined> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
};

type CursorResult = {error: string} | {cursor: SessionCursor};

function validateCursor(raw: unknown): CursorResult {
  if (typeof raw !== 'object' || raw === null) {
    return {error: 'list_sessions before must be an object'};
  }
  const {sessionId, updatedAt} = raw as Record<string, unknown>;
  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_SESSION_ID_LENGTH) {
    return {error: 'list_sessions before.sessionId must be a string of 1-128 characters'};
  }
  const isDateLike = typeof updatedAt === 'string' || typeof updatedAt === 'number';
  if (!isDateLike || !Number.isFinite(new Date(updatedAt).getTime())) {
    return {error: 'list_sessions before.updatedAt must be a date string or number'};
  }
  return {cursor: {updatedAt, sessionId}};
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const request: ListSessionsMessage = {type: 'list_sessions'};
  const {limit, before} = message;

  if (limit !== undefined) {
    if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0) {
      return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
    }
    request.limit = limit;
  }

  if (before === undefined) {
    return {valid: true, data: request};
  }
  const parsed = validateCursor(before);
  if ('error' in parsed) {
    return {valid: false, error: parsed.error};
  }
  request.before = parsed.cursor;
  return {valid: true, data: request};
}
